module remainder_game (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [15:0] k,\n    input [15:0] c_0, c_1, c_2, c_3, c_4, c_5, c_6, c_7,\n    output reg done,\n    output reg result\n);\n\n// State definitions\nlocalparam [3:0] IDLE             = 4'd0;\nlocalparam [3:0] CHECK_INDEX      = 4'd1;\nlocalparam [3:0] GET_C            = 4'd2;\nlocalparam [3:0] COMPUTE_GCD_K_C  = 4'd3;\nlocalparam [3:0] COMPUTE_GCD_L_G  = 4'd4;\nlocalparam [3:0] COMPUTE_DIV      = 4'd5;\nlocalparam [3:0] COMPUTE_MUL      = 4'd6;\nlocalparam [3:0] UPDATE_L         = 4'd7;\nlocalparam [3:0] COMPARE_RESULT   = 4'd8;\nlocalparam [3:0] DONE_STATE       = 4'd9;\n\n// Internal registers\nreg [3:0] state;\nreg [15:0] L;\nreg [3:0] index;\nreg [15:0] temp_g;\nreg [15:0] temp_h;\nreg [15:0] temp_div;\nreg [15:0] c_val;\n\n// Submodule control\nreg gcd_start, div_start;\nreg [15:0] gcd_a, gcd_b;\nreg [15:0] div_dividend, div_divisor;\n\n// Submodule outputs\nwire [15:0] gcd_result;\nwire [15:0] div_quotient;\nwire gcd_done, div_done;\n\n// Submodule instantiations\ngcd_unit gcd_inst (\n    .clk(clk),\n    .rst_n(rst_n),\n    .start(gcd_start),\n    .a(gcd_a),\n    .b(gcd_b),\n    .result(gcd_result),\n    .done(gcd_done)\n);\n\ndiv_unit div_inst (\n    .clk(clk),\n    .rst_n(rst_n),\n    .start(div_start),\n    .dividend(div_dividend),\n    .divisor(div_divisor),\n    .quotient(div_quotient),\n    .done(div_done)\n);\n\n// Main FSM\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 1'b0;\n        L <= 16'd1;\n        index <= 4'd0;\n        temp_g <= 16'd0;\n        temp_h <= 16'd0;\n        temp_div <= 16'd0;\n        c_val <= 16'd0;\n        gcd_start <= 1'b0;\n        div_start <= 1'b0;\n    end else begin\n        case(state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    L <= 16'd1;\n                    index <= 4'd0;\n                    state <= CHECK_INDEX;\n                end\n            end\n            \n            CHECK_INDEX: begin\n                if (index < n) begin\n                    state <= GET_C;\n                end else begin\n                    state <= COMPARE_RESULT;\n                end\n            end\n            \n            GET_C: begin\n                case(index)\n                    4'd0: c_val <= c_0;\n                    4'd1: c_val <= c_1;\n                    4'd2: c_val <= c_2;\n                    4'd3: c_val <= c_3;\n                    4'd4: c_val <= c_4;\n                    4'd5: c_val <= c_5;\n                    4'd6: c_val <= c_6;\n                    4'd7: c_val <= c_7;\n                    default: c_val <= 16'd0;\n                endcase\n                state <= COMPUTE_GCD_K_C;\n            end\n            \n            COMPUTE_GCD_K_C: begin\n                if (!gcd_start && !gcd_done) begin\n                    gcd_a <= k;\n                    gcd_b <= c_val;\n                    gcd_start <= 1'b1;\n                end else if (gcd_done) begin\n                    gcd_start <= 1'b0;\n                    temp_g <= gcd_result;\n                    state <= COMPUTE_GCD_L_G;\n                end\n            end\n            \n            COMPUTE_GCD_L_G: begin\n                if (!gcd_start && !gcd_done) begin\n                    gcd_a <= L;\n                    gcd_b <= temp_g;\n                    gcd_start <= 1'b1;\n                end else if (gcd_done) begin\n                    gcd_start <= 1'b0;\n                    temp_h <= gcd_result;\n                    state <= COMPUTE_DIV;\n                end\n            end\n            \n            COMPUTE_DIV: begin\n                if (!div_start && !div_done) begin\n                    div_dividend <= L;\n                    div_divisor <= temp_h;\n                    div_start <= 1'b1;\n                end else if (div_done) begin\n                    div_start <= 1'b0;\n                    temp_div <= div_quotient;\n                    state <= COMPUTE_MUL;\n                end\n            end\n            \n            COMPUTE_MUL: begin\n                L <= temp_div * temp_g;\n                state <= UPDATE_L;\n            end\n            \n            UPDATE_L: begin\n                index <= index + 4'd1;\n                state <= CHECK_INDEX;\n            end\n            \n            COMPARE_RESULT: begin\n                result <= (L == k) ? 1'b1 : 1'b0;\n                state <= DONE_STATE;\n            end\n            \n            DONE_STATE: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule\n\n// GCD module\nmodule gcd_unit (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] a,\n    input [15:0] b,\n    output reg [15:0] result,\n    output reg done\n);\n\nreg [1:0] state;\nlocalparam [1:0] IDLE = 2'd0;\nlocalparam [1:0] COMPUTE = 2'd1;\nlocalparam [1:0] FINISH = 2'd2;\n\nreg [15:0] x, y;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 16'd0;\n        x <= 16'd0;\n        y <= 16'd0;\n    end else begin\n        case(state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    x <= a;\n                    y <= b;\n                    state <= COMPUTE;\n                end\n            end\n            \n            COMPUTE: begin\n                if (x == y) begin\n                    result <= x;\n                    state <= FINISH;\n                end else if (x > y) begin\n                    x <= x - y;\n                end else begin\n                    y <= y - x;\n                end\n            end\n            \n            FINISH: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule\n\n// Division module (exact only)\nmodule div_unit (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] dividend,\n    input [15:0] divisor,\n    output reg [15:0] quotient,\n    output reg done\n);\n\nreg [1:0] state;\nlocalparam IDLE = 2'd0;\nlocalparam COMPUTE = 2'd1;\nlocalparam FINISH = 2'd2;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        quotient <= 16'd0;\n    end else begin\n        case(state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    quotient <= dividend / divisor;  // Simple exact division\n                    state <= FINISH;\n                end\n            end\n            \n            FINISH: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule